import Foundation

class Tokenizer {
    func tokenize(text: String) -> [String] {
        // Define the regular expression pattern to match whitespace characters
        let pattern = "\\s+"

        // Create a set to store the tokens
        var tokens: Set<String> = []

        // Split the text into tokens using the pattern
        let components = text.components(separatedBy: pattern)

        // Add each component to the set of tokens
        for component in components {
